int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    struct bio_vec bvec;
    unsigned int len;
    int ret = 0;

    if (!iov_iter_count(iter))
        return 0;

    if (!map_data || !q || !rq)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        len = min(iov_iter_count(iter), (size_t)PAGE_SIZE);

        bio = bio_alloc(gfp_mask, 1);
        if (!bio) {
            ret = -EINVAL;
            break;
        }

        iov_iter_get_pages(iter, &bvec, len, 1, NULL);
        bio_add_page(bio, bvec.bv_page, len, bvec.bv_offset);
        bio->bi_iter = iter->nr_segs;

        if (bio_add_to_request(rq, bio) < 0) {
            bio_put(bio);
            ret = -EINVAL;
            break;
        }
    }

    if (ret < 0) {
        bio_free(bio, gfp_mask);
        return ret;
    }

    return 0;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t offset = 0;
    struct bio *bio = NULL;
    struct bio *head = NULL;
    struct iovec *iov;
    unsigned long nr_segs;
    size_t iov_offset;
    int i;

    if (!iov_iter_count(iter))
        return 0;

    nr_segs = iov_iter_npages(iter, BIO_MAX_PAGES);
    if (nr_segs > BIO_MAX_PAGES)
        return -EINVAL;

    iov = memdup(iter->__iov, iter->nr_segs * sizeof(struct iovec), gfp_mask);
    if (!iov)
        return -EINVAL;

    iov_offset = 0;

    for (i = 0; i < iter->nr_segs; i++) {
        struct page *page;
        unsigned int len;
        unsigned int offset_in_page;
        unsigned int size;

        len = iov[i].iov_len;
        if (!len)
            continue;

        page = virt_to_page((void *)((unsigned long)iov[i].iov_base + iov_offset));
        if (!page) {
            kfree(iov);
            bio_free(bio);
            return -EINVAL;
        }

        offset_in_page = offset_in_page(iov[i].iov_base + iov_offset);
        size = min_t(size_t, len, PAGE_SIZE - offset_in_page);

        if (!bio) {
            bio = bio_alloc(gfp_mask, 0);
            if (!bio) {
                kfree(iov);
                return -EINVAL;
            }
            bio->bi_bdev = map_data->bdev;
            bio->bi_sector = map_data->offset >> 9;
            head = bio;
        }

        bio_add_page(bio, page, size, offset_in_page);
        offset += size;

        if (offset == len) {
            bio = NULL;
        } else {
            struct bio *new_bio = bio_alloc(gfp_mask, 0);
            if (!new_bio) {
                kfree(iov);
                bio_free(bio);
                return -EINVAL;
            }
            new_bio->bi_bdev = map_data->bdev;
            new_bio->bi_sector = map_data->offset >> 9;
            bio->bi_next = new_bio;
            bio = new_bio;
        }

        iov_offset += len;
    }

    kfree(iov);

    if (!head)
        return 0;

    rq->biotail->bi_next = head;

    return 0;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    unsigned int nr_mapped = 0;
    struct bio *bio = NULL;
    struct bio *prev = NULL;
    int ret = 0;

    if (!iov_iter_count(iter) || !map_data)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        struct iovec iov;
        size_t iov_len;

        iov_len = min(iov_iter_single_seg_size(iter), (size_t)QUEUE_MAX_SEGMENTS(q));
        if (!iov_len)
            break;

        new_bio = bio_alloc(GFP_NOIO, 1);
        if (!new_bio) {
            ret = -EINVAL;
            break;
        }

        iov.iov_base = iter->iov->iov_base;
        iov.iov_len = iov_len;
        new_bio->bi_io_vec[0].bv_page = virt_to_page(iov.iov_base);
        new_bio->bi_io_vec[0].bv_offset = offset_in_page(iov.iov_base);
        new_bio->bi_io_vec[0].bv_len = iov_len;

        new_bio->bi_sector = map_data->sector + nr_mapped * (iov_len >> 9);
        new_bio->bi_bdev = map_data->bdev;
        new_bio->bi_end_io = NULL;
        new_bio->bi_private = NULL;

        if (prev)
            prev->bi_next = new_bio;
        else
            rq->bio = new_bio;

        prev = new_bio;
        nr_mapped++;
        iov_iter_advance(iter, iov_len);
    }

    if (ret)
        bio_unmap_user(rq->bio);

    if (!nr_mapped)
        return -EINVAL;

    rq->nr_phys_segments = nr_mapped;
    rq->__data_len = iov_iter_count(iter);
    rq->cmd_flags |= REQ_USER_MAPPED;

    return 0;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t len;
    int ret = -EINVAL;

    if (!iov_iter_count(iter))
        return 0;

    if (!map_data)
        return -EINVAL;

    len = iov_iter_count(iter);

    if (iov_iter_is_bvec(iter)) {
        struct bio *bio;
        struct bvec_iter bvec;

        bio = bio_alloc(gfp_mask, 1);
        if (!bio)
            return -ENOMEM;

        bio->bi_bdev = map_data->bdev;
        bio->bi_iter.bi_sector = map_data->start;

        bvec = *iter->bvec;
        while (bvec.bv) {
            if (bio_add_page(bio, bvec.bv_page, bvec.bv_len, bvec.bv_offset) != bvec.bv_len) {
                ret = -ENOMEM;
                goto out;
            }
            bvec = *iov_iter_next_bvec(iter);
        }

        ret = 0;
        rq->cmd_flags |= REQ_BIO;
        rq->biotail = bio;
    } else {
        struct bio *bio;
        struct page *page;
        unsigned int offset, bytes;

        bio = bio_alloc(gfp_mask, 1);
        if (!bio)
            return -ENOMEM;

        bio->bi_bdev = map_data->bdev;
        bio->bi_iter.bi_sector = map_data->start;

        while (iov_iter_count(iter)) {
            struct iov_iter i;
            struct page *pages[1];
            int nr_pages = 0;
            int ret2;

            iov_iter_init(&i, *iter);
            ret2 = iov_iter_get_pages(&i, pages, iov_iter_count(&i), 1, &offset);
            if (ret2 <= 0)
                break;

            bytes = ret2;
            if (bio_add_page(bio, pages[0], bytes, offset) != bytes) {
                ret = -ENOMEM;
                goto out;
            }
        }

        if (iov_iter_count(iter)) {
            ret = -EINVAL;
            goto out;
        }

        ret = 0;
        rq->cmd_flags |= REQ_BIO;
        rq->biotail = bio;
    }

    return ret;

out:
    bio_put(bio);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    size_t len;
    struct bio *bio = NULL;
    struct page *page = NULL;

    if (!iov_iter_count(iter))
        return -EINVAL;

    if (unlikely(iter->nr_segs > BIO_MAX_PAGES))
        return -EINVAL;

    if (map_data->offset + iov_iter_count(iter) > queue_max_hw_sectors(q) * 512)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct iovec iovec;
        size_t seg_len;

        seg_len = iov_iter_iovec(iter, &iovec);
        len = seg_len;

        if (!bio) {
            bio = bio_alloc(gfp_mask, 1);
            if (!bio)
                return -EINVAL;
        }

        if (iovec.iov_len < len)
            len = iovec.iov_len;

        if (!iov_iter_is_bvec(iter)) {
            if (iovec.iov_base == NULL) {
                ret = -EINVAL;
                goto cleanup;
            }

            page = alloc_page(gfp_mask);
            if (!page) {
                ret = -EINVAL;
                goto cleanup;
            }

            if (copy_from_user(page_address(page), iovec.iov_base, len)) {
                __free_page(page);
                ret = -EFAULT;
                goto cleanup;
            }

            bio_add_page(bio, page, len, 0);
        } else {
            struct bio_vec *bvec = &map_data->bvecs[map_data->nr_bvecs];
            struct page *src_page = iovec.iov_base;

            if (!src_page) {
                ret = -EINVAL;
                goto cleanup;
            }

            bio_add_page(bio, src_page, len, iovec.iov_len - len);
        }

        map_data->nr_bvecs++;
        if (map_data->nr_bvecs == BIO_MAX_PAGES) {
            ret = -EINVAL;
            goto cleanup;
        }
    }

    if (!bio)
        return -EINVAL;

    bio->bi_end_io = end_bio;
    submit_bio(REQ_OP_WRITE, bio);
    return 0;

cleanup:
    if (bio)
        bio_put(bio);
    if (page)
        __free_page(page);
    return ret;
}
